import { useEffect, useState } from "react";
import api from "@/lib/api";
import { Link, Navigate } from "react-router-dom";
import { useAuth } from "@/context/AuthContext";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";

const STATUS_STYLE = {
  placed: "bg-amber-100 text-amber-800",
  confirmed: "bg-blue-100 text-blue-800",
  rider_assigned: "bg-indigo-100 text-indigo-800",
  delivered: "bg-green-100 text-green-800",
  cancelled: "bg-red-100 text-red-800",
  pending: "bg-amber-100 text-amber-800",
  approved: "bg-emerald-100 text-emerald-800",
  rejected: "bg-red-100 text-red-800",
};

const formatDateTime = (value) => {
  if (!value) return "—";
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? "—" : date.toLocaleString();
};

export default function MyOrders() {
  const { user, loading } = useAuth();
  const [orders, setOrders] = useState([]);
  const [customCakes, setCustomCakes] = useState([]);

  useEffect(() => {
    if (!user) return;
    api.get("/orders/my").then((r) => setOrders(r.data));
    api.get("/custom-cakes/my").then((r) => setCustomCakes(r.data));
  }, [user]);

  if (loading) return <div className="py-20 text-center">Loading...</div>;
  if (!user) return <Navigate to="/login" />;

  const items = [...orders.map((o) => ({ ...o, itemType: "order" })), ...customCakes.map((c) => ({ ...c, itemType: "custom" }))]
    .sort((a, b) => new Date(b.created_at) - new Date(a.created_at));

  return (
    <div className="max-w-5xl mx-auto px-4 py-10" data-testid="my-orders-page">
      <h1 className="font-display text-3xl md:text-4xl font-bold mb-6">My Orders</h1>
      {items.length === 0 ? (
        <div className="text-center py-16 text-[#5C4A3D]">No orders yet. <Link to="/categories" className="text-[#D97706] font-semibold">Start shopping</Link></div>
      ) : (
        <div className="space-y-3">
          {items.map((o) => {
            const isCustom = o.itemType === "custom";
            const detailLink = isCustom ? `/custom-cakes/${o.id}` : `/orders/${o.id}`;
            const subtitle = isCustom
              ? `${o.quantity} qty · ${o.custom_price ? `₹${o.custom_price}` : "Price pending"}`
              : `${o.items?.length} items · ₹${o.total?.toFixed(0)} · ${o.payment_method}`;
            const heading = isCustom ? `Custom Cake Request #${o.id.slice(-6)}` : o.order_no;

            return (
              <div key={o.id} className="bg-white border border-[#E6DFD5] rounded-2xl p-5 flex flex-col md:flex-row gap-4 md:items-center" data-testid={isCustom ? `custom-order-${o.id}` : `order-${o.order_no}`}>
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <div className="font-semibold">{heading}</div>
                    <Badge className={STATUS_STYLE[o.status] || "bg-slate-100 text-slate-800"}>{o.status.replace("_", " ")}</Badge>
                  </div>
                  <div className="text-xs text-[#5C4A3D] mt-1">
                    <div>{isCustom ? "Custom cake request" : "Order"}</div>
                    <div>Ordered: {formatDateTime(o.created_at)}</div>
                    {o.status === "delivered" && o.delivered_at && (
                      <div>Delivered: {formatDateTime(o.delivered_at)}</div>
                    )}
                  </div>
                  <div className="text-sm mt-2">{subtitle}</div>
                  {o.status === "cancelled" && o.cancellation_reason && (
                    <div className="text-sm text-red-600 mt-2">Cancellation reason: {o.cancellation_reason}</div>
                  )}
                </div>
                <Link to={detailLink}><Button variant="outline" className="rounded-full">View Details</Button></Link>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
